CREATE OR REPLACE FUNCTION public.guard_cj_price_floor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rate numeric; cost numeric; markup numeric; target numeric; floor_price numeric; BEGIN IF NEW.supplier IS DISTINCT FROM 'cj' THEN RETURN NEW; END IF; SELECT commission_rate INTO rate FROM public.platform_settings WHERE id=true; IF rate IS NULL OR rate<0 OR rate>=1 OR NEW.supplier_cost IS NULL OR NEW.supplier_exchange_rate IS NULL OR NEW.supplier_cost<=0 OR NEW.supplier_exchange_rate<=0 THEN NEW.is_active:=false; RETURN NEW; END IF; cost:=ceil(NEW.supplier_cost*NEW.supplier_exchange_rate*100)/100; markup:=CASE WHEN cost<=30 THEN 1.2 WHEN cost<=100 THEN .6 WHEN cost<=300 THEN .4 WHEN cost<=1000 THEN .2 WHEN cost<=2000 THEN .14 WHEN cost<=5000 THEN .09 WHEN cost<=10000 THEN .07 ELSE .05 END; target:=cost*(1+markup); floor_price:=ceil(target/(1-rate)*100)/100; NEW.price:=greatest(NEW.price,floor_price); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_cj_price_floor() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER cj_price_floor BEFORE INSERT OR UPDATE OF price,supplier_cost,supplier_exchange_rate,is_active ON public.products FOR EACH ROW EXECUTE FUNCTION public.guard_cj_price_floor();
CREATE OR REPLACE FUNCTION public.guard_cj_order_profit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.shipping_quotes%ROWTYPE; target numeric; supplier_total numeric; rate numeric; BEGIN SELECT sq.* INTO q FROM public.order_shipments os JOIN public.shipping_quotes sq ON sq.id=os.quote_id WHERE os.order_id=NEW.order_id AND os.store_id=NEW.store_id AND sq.provider='cj'; IF NOT FOUND THEN RETURN NEW; END IF; IF q.provider_payload->>'profit_guard_version' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'Atualize a cotação CJ para proteger o custo e a margem antes de pagar.'; END IF; SELECT commission_rate INTO rate FROM public.platform_settings WHERE id=true; IF rate IS DISTINCT FROM (q.provider_payload->>'commission_rate')::numeric THEN RAISE EXCEPTION 'A comissão mudou. Atualize a cotação CJ.'; END IF; SELECT sum((value->>'supplier_item_cost_brl')::numeric*(value->>'quantity')::integer) INTO supplier_total FROM jsonb_array_elements(q.provider_payload->'priced_items'); supplier_total:=supplier_total+(q.provider_payload->>'supplier_freight_brl')::numeric; target:=(q.provider_payload->>'protected_net_target')::numeric; IF supplier_total IS NULL OR target IS NULL OR NEW.seller_amount < greatest(supplier_total,target)-0.02 THEN RAISE EXCEPTION 'Compra bloqueada: valor disponível não cobre custo e margem CJ. Atualize a cotação.'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_cj_order_profit() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER cj_order_profit BEFORE INSERT OR UPDATE OF gross_amount,platform_fee,seller_amount ON public.payment_transactions FOR EACH ROW EXECUTE FUNCTION public.guard_cj_order_profit();